test("部品のルートの幅が fill のインスタンスを包むと、Box の幅も fill になる", () => {
  const document = setupArtboardDocument({
    components: { card: { type: "Box", props: { widthMode: "fill" } } },
    children: [{ name: "hero", ref: "card" }],
  });

  expect(propsOf(group(document, ["hero"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("部品のルートの高さが下限・上限の付いた fill のインスタンスを包むと、Box も同じ高さの下限・上限を持つ", () => {
  const document = setupArtboardDocument({
    components: {
      card: {
        type: "Box",
        props: { heightMode: "fill", minHeight: 40, maxHeight: 160 },
      },
    },
    children: [{ name: "hero", ref: "card" }],
  });

  expect(propsOf(group(document, ["hero"]), "box")).toEqual({
    heightMode: "fill",
    minHeight: 40,
    maxHeight: 160,
  });
});

test("公開 prop で部品のルートの幅を fill に上書きしたインスタンスを包むと、Box の幅も fill になる", () => {
  const document = setupArtboardDocument({
    components: {
      card: {
        type: "Box",
        props: { widthMode: "hug" },
        publicProps: { width: { node: "card", prop: "widthMode" } },
      },
    },
    children: [{ name: "hero", ref: "card", overrides: { width: "fill" } }],
  });

  expect(propsOf(group(document, ["hero"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("layout: free の親の下で部品のルートの幅が fill のインスタンスを包んだ Box は、大きさの prop を持たない", () => {
  const document = setupArtboardDocument({
    artboardProps: { layout: "free" },
    components: { card: { type: "Box", props: { widthMode: "fill" } } },
    children: [{ name: "hero", ref: "card" }],
  });

  expect(propsOf(group(document, ["hero"]), "box")).toEqual({});
});

test("参照先の部品が無いインスタンスを包むと、包めて、Box は大きさの prop を持たない", () => {
  const document = setupArtboardDocument({
    children: [{ name: "hero", ref: "missing" }],
  });

  const grouped = DesignDocument.groupIntoBox(document, ["hero"], "box");

  expect(Result.map(grouped, (done) => propsOf(done, "box"))).toEqual(
    Result.ok({}),
  );
});

test("layout: row と書いた親の下で部品のルートの幅が fill のインスタンスを包むと、Box の幅も fill になる", () => {
  const document = setupArtboardDocument({
    artboardProps: { layout: "row" },
    components: { card: { type: "Box", props: { widthMode: "fill" } } },
    children: [{ name: "hero", ref: "card" }],
  });

  expect(propsOf(group(document, ["hero"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("layout: free の親の下で幅が fill のプリミティブを包むと、Box の幅も fill になる", () => {
  const document = setupArtboardDocument({
    artboardProps: { layout: "free" },
    children: [
      { name: "card", type: "Box", props: { widthMode: "fill" }, children: [] },
    ],
  });

  expect(propsOf(group(document, ["card"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("兄弟のうち部品のルートの幅が fill のインスタンスがあれば、Box の幅も fill になり、下限・上限は写さない", () => {
  const document = setupArtboardDocument({
    components: {
      card: {
        type: "Box",
        props: { widthMode: "fill", minWidth: 120, maxWidth: 320 },
      },
    },
    children: [
      { name: "first", ref: "card" },
      { name: "second", type: "Box" },
    ],
  });

  expect(propsOf(groupPair(document), "box")).toEqual({ widthMode: "fill" });
});

test("layout: free の親の中で部品のルートの幅が fill のインスタンスを兄弟と包むと、Box は free だけを持ち fill を持たない", () => {
  const document = setupArtboardDocument({
    artboardProps: { layout: "free" },
    components: { card: { type: "Box", props: { widthMode: "fill" } } },
    children: [
      { name: "first", ref: "card" },
      { name: "second", type: "Box" },
    ],
  });

  expect(propsOf(groupPair(document), "box")).toEqual({ layout: "free" });
});

test("揃えが stretch の親の下で部品のルートが Text のインスタンスを包むと、Box の幅が fill になる", () => {
  const document = setupArtboardDocument({
    components: { caption: { type: "Text" } },
    children: [{ name: "label", ref: "caption" }],
  });

  expect(propsOf(group(document, ["label"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("揃えが stretch の親の下で部品のルートが Box のインスタンスを包んだ Box は、大きさの prop を持たない", () => {
  const document = setupArtboardDocument({
    components: { card: { type: "Box" } },
    children: [{ name: "hero", ref: "card" }],
  });

  expect(propsOf(group(document, ["hero"]), "box")).toEqual({});
});

test("layout: row と書いた artboard の直下で部品のルートが Text のインスタンスを包むと、Box の高さが fill になる", () => {
  const document = setupArtboardDocument({
    artboardProps: { layout: "row" },
    components: { caption: { type: "Text" } },
    children: [{ name: "label", ref: "caption" }],
  });

  expect(propsOf(group(document, ["label"]), "box")).toEqual({
    heightMode: "fill",
  });
});

test("揃えが stretch の親の下で部品のルートが Text のインスタンスと Box をまとめて包むと、Box の幅が fill になる", () => {
  const document = setupArtboardDocument({
    components: { caption: { type: "Text" } },
    children: [
      { name: "label", ref: "caption" },
      { name: "card", type: "Box" },
    ],
  });

  expect(propsOf(group(document, ["label", "card"]), "box")).toEqual({
    widthMode: "fill",
  });
});

test("揃えが stretch の親の下で部品のルートが Text のインスタンスを包んでから外すと、元のドキュメントに戻る", () => {
  const document = setupArtboardDocument({
    components: { caption: { type: "Text" } },
    children: [{ name: "label", ref: "caption" }],
  });

  const ungrouped = Result.unwrap(
    DesignDocument.ungroupBox(group(document, ["label"]), "box"),
  );

  expect(ungrouped.document).toEqual(document);
});

function rootNodeOf(
  document: DesignDocument,
  node: Node,
): Option<PrimitiveNode> {
  if (Node.isPrimitive(node)) {
    return Option.some(node);
  }
  return Option.map(
    ComponentSet.get(document.components, node.ref),
    (component) =>
      Component.toNode(
        Component.applyOverrides(component, node.ref, node.overrides ?? {}),
        node.name,
      ),
  );
}

function fillSourcePropsOf(member: GroupMember, parentProps: Props): Props {
  const parentArrangesChildren = Option.isSome(
    Layout.direction(Layout.fromProps(parentProps)),
  );
  const isInstanceInFreeParent =
    !Node.isPrimitive(member.node) && !parentArrangesChildren;

  if (isInstanceInFreeParent) {
    return {};
  }

  return Option.unwrapOr(Option.map(member.root, Node.propsOf), {});
}
